do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int; isnew boolean;
begin
insert into public.companies(ticker,name,segment,size_tier,is_seed,is_hero,markets,exchange,country) values ($q$VOD$q$,$q$Vodafone Group$q$,null,null,true,false,array[$q$LSE$q$,$q$US$q$]::text[],null,$q$GB$q$) on conflict (ticker) do update set is_seed=true, segment=excluded.segment, size_tier=excluded.size_tier, is_hero=excluded.is_hero, markets=case when cardinality(excluded.markets)>0 then excluded.markets else public.companies.markets end, exchange=coalesce(excluded.exchange, public.companies.exchange), country=coalesce(excluded.country, public.companies.country);
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$Accenture$q$,$q$public_company$q$),($q$CK Hutchison$q$,$q$public_company$q$),($q$Liberty Global$q$,$q$public_company$q$),($q$M-Pesa Holding Company Limited$q$,$q$private_company$q$),($q$Safaricom$q$,$q$public_company$q$),($q$Swisscom$q$,$q$public_company$q$),($q$Vodafone Italia$q$,$q$private_company$q$),($q$Vodafone Shared Operations$q$,$q$private_company$q$),($q$Vodafone Spain$q$,$q$private_company$q$),($q$VodafoneThree$q$,$q$private_company$q$),($q$VodafoneZiggo$q$,$q$private_company$q$),($q$Zegona$q$,$q$public_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$Accenture Holdings B.V. holds 20% of the total voting rights in Vodafone Shared Operations Limited.$q$),(2,$q$Between (i) 20 May 2025 and 23 July 2025, (ii) 24 July 2025 and 10 November 2025, (iii) 11 November 2025 and 4 February 2026 and (iv) 5 February 2026 and 11 May 2026, Vodafone undertook non-discretionary share buyback programmes with Citigroup Global Markets Limited, Goldman Sachs International, Merrill Lynch International and Goldman Sachs International respectively following the sale of Vodafone Italy to Swisscom AG.$q$),(3,$q$Following completion, VTHL is a subsidiary of the Group, in which the Group owns 51% of the issued share capital and CKHGT indirectly owns 49%, and Vodafone UK and Three UK are wholly owned subsidiaries of VTHL.$q$),(4,$q$Following the completion of the sale of Vodafone Spain on 31 May 2024 (See note 7 ‘Discontinued operations and assets held for sale’), the Group received the non-cash consideration component in the form of €900 million Redeemable Preference Shares (‘RPS’) issued by EJLSHM Funding Ltd (‘EJLSHM’). The RPS were redeemed in January 2026. The Zegona shares were recorded at fair value through profit and loss and had a fair value of €937 million on 31 March 2025.$q$),(5,$q$In February 2026, we announced that we agreed to sell our interests in VodafoneZiggo to Liberty Global for €1.0 billion in cash and a 10% equity stake in a soon-to-be-formed Benelux entity (Ziggo Group), which will own 100% of both VodafoneZiggo and Liberty Global’s Belgian subsidiary, Telenet Group Holding2.$q$),(6,$q$In the comparative year, on 31 December 2024, the Group announced it had completed the sale of Vodafone Italia S.p.A. (‘Vodafone Italy’) to Swisscom AG for €7,885 million in cash (subject to closing accounts adjustments, which were finalised during the year ended 31 March 2026).$q$),(7,$q$In the comparative year, on 31 May 2024, the Group announced it had completed the sale of Vodafone Holdings Europe, S.L.U. (‘Vodafone Spain’) to Zegona Communications plc (‘Zegona’) for €4,069 million in cash (subject to closing accounts adjustments, which were finalised during the year ended 31 March 2026) and up to €900 million of non-cash consideration in the form of redeemable preference shares, which were settled during the year ended 31 March 2026.$q$),(8,$q$On 15 March 2024, the Group announced that it had entered into a binding agreement with Swisscom AG (‘Swisscom’) in relation to the disposal of 100% of Vodafone Italia S.p.A. (’Vodafone Italy’).$q$),(9,$q$On 18 February 2026, Vodafone Group Plc announced that it agreed to sell its 50% interest in VodafoneZiggo Group Holding B.V. (‘VodafoneZiggo’) to Liberty Global plc (‘Liberty Global’) for €1.0 billion in cash and a 10% shareholding in a soon-to-be-formed Benelux entity (‘Ziggo Group’), which will own 100% of both VodafoneZiggo and Liberty Global’s Belgian subsidiary, Telenet Group Holding (‘Telenet’).$q$),(10,$q$On 18 February 2026, the Group announced that it has agreed to sell its interests in VodafoneZiggo Group Holding B.V. (‘VodafoneZiggo’) to Liberty Global plc for €1.0 billion in cash and a 10% stake in the new Ziggo Group which will own 100% of both VodafoneZiggo and Liberty Global’s Belgian subsidiary, Telenet Group Holding.$q$),(11,$q$On 18 February 2026, we announced our agreement to sell our interests in VodafoneZiggo Group Holding B.V. to Liberty Global plc for €1.0 billion in cash and a 10% shareholding in a soon-to-be-formed Benelux entity, which will own 100% of both VodafoneZiggo and Liberty Global’s Belgian subsidiary, Telenet Group Holding.$q$),(12,$q$On 28 September 2023, the Group sold M-Pesa Holding Company Limited which holds funds on trust for M-Pesa customers, to Safaricom Plc for US$1.$q$),(13,$q$On 31 October 2023, the Group announced that it had entered into binding agreements with Zegona Communications plc (’Zegona’) in relation to the disposal of 100% of Vodafone Holdings Europe, S.L.U. (‘Vodafone Spain’).$q$),(14,$q$On 5 May 2026, the Group announced that it had reached an agreement for the buyout of CK Hutchison Group Telecom Holding Limited’s (‘CKHGT’) 49% interest in VodafoneThree Holdings Limited (‘VodafoneThree’) for £4.3 billion (€4.9 billion) cash, implemented through a cancellation of CKHGT’s shares.$q$),(15,$q$The Board approved the buyout of CK Hutchison Group Telecom Holding Limited from the VodafoneThree joint venture for £4.3 billion (€4.9 billion) via a cancellation of shares.$q$),(16,$q$The Board approved the sale of Vodafone’s interests in VodafoneZiggo to Liberty Global for €1 billion in cash and a 10% shareholding in a future Benelux entity comprising VodafoneZiggo and Telenet.$q$),(17,$q$The aggregate net cash received in respect of other transactions with non-controlling shareholders in subsidiaries was €100 million (2025: €8 million) including €125 million (2025: €25 million) received from Accenture Holdings B.V. for a non-controlling interest in Vodafone Shared Operations Limited.$q$),(18,$q$Vodafone Italia S.p.A’s (‘Vodafone Italy’s’) defined contribution and defined benefit schemes have been transferred to Swisscom AG (see note 27 ‘Acquisitions and disposals’).$q$),(19,$q$settlement in the current year of redeemable preference shares provided by Zegona Communications Plc as part of the disposal of Vodafone Spain$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$acquires$q$,$q$Liberty Global$q$,$q$VodafoneZiggo$q$,$q${5,16,10,9,11}$q$::int[],$q${p19,p87,p165,p244,p74}$q$::text[],null,null,null,null),(2,$q$acquires$q$,$q$Zegona$q$,$q$Vodafone Spain$q$,$q${19,13,4,7}$q$::int[],$q${p21,p164,p194,p203}$q$::text[],null,null,null,null),(3,$q$acquires$q$,$q$Safaricom$q$,$q$M-Pesa Holding Company Limited$q$,$q${12}$q$::int[],$q${p23}$q$::text[],null,null,null,null),(4,$q$invests$q$,$q$CK Hutchison$q$,$q$VodafoneThree$q$,$q${15,14,3}$q$::int[],$q${p87,p220,p20}$q$::text[],null,null,null,null),(5,$q$acquires$q$,$q$Swisscom$q$,$q$Vodafone Italia$q$,$q${8,6,2,18}$q$::int[],$q${p164,p203,p239,p196}$q$::text[],100,$q$exact$q$,$q$ownership$q$,null),(6,$q$invests$q$,$q$Accenture$q$,$q$Vodafone Shared Operations$q$,$q${17,1}$q$::int[],$q${p202,p219}$q$::text[],null,null,null,null);
create or replace function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$VOD$q$ then ticker=$q$VOD$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,cost_usd,status,review_status) values ('filings_extraction','batch',$q$VOD FY2026 annual report, extension edges (M14)$q$,'claude-sonnet-5-5 via Claude Code session',0.0,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; isnew := false; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,trust_status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else $q$2026-03-31$q$::date end,$q$annual_report$q$,$q$staged$q$,null,run_id,$q$2026-03-31$q$::date,r.note) returning id into rid; isnew := true; end if; if isnew then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,null,r.sec[k],t,true,null from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;
